+const IDENTIFIER = "[0-9A-Za-z-]+";
+const VERSION_PATTERN = new RegExp(
+  `^\\s*v?(\\d+)\\.(\\d+)\\.(\\d+)(?:-(${IDENTIFIER}(?:\\.${IDENTIFIER})*))?(?:\\+(?:${IDENTIFIER})(?:\\.(?:${IDENTIFIER}))*)?\\s*$`,
+);
+
 /** Parse a version string. See README.md for the accepted syntax. */
 export function parseVersion(text: string): Version {
-  throw new Error("not implemented");
+  const match = text.match(VERSION_PATTERN);
+  if (match === null) {
+    throw new Error(`invalid version: ${text}`);
+  }
+  return {
+    major: Number(match[1]),
+    minor: Number(match[2]),
+    patch: Number(match[3]),
+    prerelease: match[4] ? match[4].split(".") : [],
+  };
+}
+
+function compareIdentifiers(a: string, b: string): number {
+  const aNumeric = /^\d+$/.test(a);
+  const bNumeric = /^\d+$/.test(b);
+  if (aNumeric && bNumeric) return Number(a) - Number(b);
+  if (aNumeric) return -1;
+  if (bNumeric) return 1;
+  return a < b ? -1 : a > b ? 1 : 0;
+}
+
+function comparePrereleases(a: string[], b: string[]): -1 | 0 | 1 {
+  const shared = Math.min(a.length, b.length);
+  for (let i = 0; i < shared; i++) {
+    const cmp = compareIdentifiers(a[i], b[i]);
+    if (cmp !== 0) return cmp < 0 ? -1 : 1;
+  }
+  if (a.length === b.length) return 0;
+  return a.length < b.length ? -1 : 1;
 }

